import("regexp";"sort";"strconv";"strings")
func QuotaLedger(s string)(string,bool){p:=strings.Split(s,";");if len(p)!=2||p[1]==""{return "",false};limit,e:=strconv.Atoi(p[0]);if e!=nil||limit<0||limit>10000000||strconv.Itoa(limit)!=p[0]{return "",false};k:=regexp.MustCompile(`^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$`);d:=map[string]int{};for _,r:=range strings.Split(p[1],","){q:=strings.Split(r,":");if len(q)!=2||!k.MatchString(q[0]){return "",false};v,e:=strconv.Atoi(q[1]);if e!=nil||v < -10000000||v>10000000||strconv.Itoa(v)!=q[1]{return "",false};n:=d[q[0]]+v;if n<0||n>limit{return "",false};d[q[0]]=n};keys:=[]string{};for x:=range d{keys=append(keys,x)};sort.Strings(keys);o:=[]string{};for _,x:=range keys{o=append(o,x+"="+strconv.Itoa(d[x]))};return strings.Join(o,","),true}
